package server

import (
	"embed"
	"errors"
	"io/fs"
	"net/http"
	"path"
	"strconv"
	"strings"

	"github.com/LatticeNet/lattice-server/internal/notify"
)

// notifyIconPathPrefix serves the notification icons a Bark push shows
// (design-notify-abstraction section 13.2).
//
// Public on purpose: Bark and the phone fetch the icon without a Lattice
// session. The set is fixed at build time, one PNG per glyph and tone the
// catalogue can produce, generated by scripts/notify-icons and embedded, so
// a file name carries nothing about the fleet. Anything that is not one of
// those files answers 404, and there is no listing.
const notifyIconPathPrefix = "/notify-icons/"

// notifyIconCacheControl lets every cache keep an icon for a year: a name
// always means the same picture, and a changed picture gets a new name.
const notifyIconCacheControl = "public, max-age=31536000, immutable"

//go:embed notifyicons/*.png
var notifyIconFS embed.FS

// notifyIcons maps each embedded file name to its bytes.
var notifyIcons = func() map[string][]byte {
	names, err := fs.Glob(notifyIconFS, "notifyicons/*.png")
	if err != nil {
		panic(err)
	}
	out := make(map[string][]byte, len(names))
	for _, name := range names {
		data, err := notifyIconFS.ReadFile(name)
		if err != nil {
			panic(err)
		}
		out[path.Base(name)] = data
	}
	return out
}()

// presentNotifyMessage is m as a channel of kind presents it (design section
// 13.2). A Bark push goes out grouped under its category's label, so iOS
// stacks a node outage apart from a login, and carries the catalogue icon
// when the server has a public URL to serve it from. The channel's own
// group, when the operator set one, still wins (notify.Bark). Other kinds
// are unchanged in this slice.
func (s *Server) presentNotifyMessage(kind string, m notify.Message, eventType, source string) notify.Message {
	if kind != "bark" {
		return m
	}
	e := s.notifyCatalogueEntryOf(eventType, source)
	m.Group = notifyCategoryLabel(e.Category)
	m.Icon = s.notifyIconURL(e.notifyPresentation)
	return m
}

// notifyIconFile names the icon of a glyph in a tone.
func notifyIconFile(icon, tone string) string { return icon + "-" + tone + ".png" }

// notifyIconURL is where a push fetches its icon, or "" when the server has
// no public URL, in which case no icon is sent.
func (s *Server) notifyIconURL(p notifyPresentation) string {
	base := strings.TrimRight(s.publicURL, "/")
	if base == "" {
		return ""
	}
	return base + notifyIconPathPrefix + notifyIconFile(p.Icon, p.tone())
}

func (s *Server) handleNotifyIcon(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet && r.Method != http.MethodHead {
		writeError(w, http.StatusMethodNotAllowed, errors.New("method not allowed"))
		return
	}
	// The name must be exactly one embedded file: an empty name, another
	// segment or a dot segment is simply not in the map.
	body, ok := notifyIcons[strings.TrimPrefix(r.URL.Path, notifyIconPathPrefix)]
	if !ok {
		http.NotFound(w, r)
		return
	}
	w.Header().Set("Content-Type", "image/png")
	w.Header().Set("Cache-Control", notifyIconCacheControl)
	w.Header().Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(http.StatusOK)
	if r.Method == http.MethodGet {
		_, _ = w.Write(body)
	}
}

// notifyIconsFirst hands every path under notifyIconPathPrefix to the icon
// handler before the ServeMux sees it. The mux answers a path holding a dot
// segment with a redirect to its cleaned form, which leaves the icon route
// for the console's static handler; the icon route answers 404 instead, so
// nothing but its own files is ever reached through it.
func (s *Server) notifyIconsFirst(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if strings.HasPrefix(r.URL.Path, notifyIconPathPrefix) {
			s.handleNotifyIcon(w, r)
			return
		}
		next.ServeHTTP(w, r)
	})
}
